record('university-of-texas-at-dallas',[route(applicability={'label':L('2026 undergraduate catalogue; Fall 2027 not established','Каталог бакалавриата 2026; Fall 2027 не установлен'),'entryYears':[2026],'status':'previous-cycle'},english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':80}]},'alternatives':L('PTE 67, DET 105 or ELS 112; SAT EBRW 560/ACT English 21 are language alternatives, not TSI registration cutoffs.','PTE 67, DET 105 либо ELS 112; SAT EBRW 560/ACT English 21 — языковые альтернативы, не пороги TSI регистрации.'),'waiver':L('Three years at a US high school plus graduation, qualifying English-country education or specified US college credits/English courses may satisfy the requirement. The conditions must be assessed together.','Три года школы США с выпуском, подходящее образование англоязычной страны либо указанные кредиты/English колледжа США могут выполнить требование. Условия оцениваются совместно.')},academic={'satPolicy':'unknown','note':L('The language section does not establish an optional academic selection policy. TSI readiness is a separate pre-enrolment requirement.','Языковой раздел не устанавливает test-optional политику академического отбора. Готовность TSI — отдельное условие до регистрации.')},sources=[s('https://catalog.utdallas.edu/2026/undergraduate/admission/international-student-admission','UT Dallas 2026 international undergraduate catalogue','UT Dallas: каталог международного бакалавриата 2026')])],'Recovered the correct undergraduate catalogue section and separated English alternatives, TSI and future-cycle confirmation.', ['Fall 2027 requirements, independent SAT/ACT policy, IELTS variant/sections and new TOEFL scale remain unconfirmed.'])

record('high-point-university',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':80},{'period':'post2026','min':4}]},'alternatives':L('DET 105, iTEP 3.8, SAT English 500 or ACT English 20. The MET row is malformed (54 and 77); no MET cutoff is asserted here.','DET 105, iTEP 3,8, SAT English 500 либо ACT English 20. Строка MET повреждена (54 и 77); порог MET здесь не утверждается.'),'waiver':L('Listed English-country cases or two consecutive years plus graduation at an accredited US high school. ESL placement after admission may still require credit-bearing support.','Указанные случаи англоязычной страны либо два последовательных года с выпуском аккредитованной школы США. Распределение ESL после приёма всё ещё может назначить кредитную поддержку.')},academic={'satPolicy':'optional','note':L('International page explicitly does not require SAT/ACT, though scores can support English proof or scholarships.','Международная страница прямо не требует SAT/ACT, хотя они могут подтверждать английский либо поддерживать стипендиальную заявку.')},note=L('Applicants below English readiness may receive conditional INTERLINK admission; completion is required before full admission. No lower direct-entry cutoff is inferred.','При недостаточном английском возможен условный INTERLINK; для полного приёма требуется его завершение. Пониженный порог прямого поступления не предполагается.'),sources=[s('https://www.highpoint.edu/admissions/international-admissions/','HPU international first-year tests and conditional language route','HPU: международные тесты первокурсника и условный языковой маршрут')])],'Separated optional academic tests, language alternatives and conditional INTERLINK; flagged the malformed MET row.', ['Fall 2027-labelled rules, IELTS variant/sections and the conflicting MET number remain unconfirmed.'])

