record('university-of-dallas',[route(english={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5},'toefl':{'accepted':True,'scales':[{'period':'pre2026','min':80},{'period':'post2026','min':4.5}]},'alternatives':L('DET 110; SAT EBRW 600 or ACT English 25 can satisfy English. This is University of Dallas in Irving, not UT Dallas in Richardson.','DET 110; SAT EBRW 600 либо ACT English 25 могут подтвердить английский. Это University of Dallas в Irving, не UT Dallas в Richardson.')},academic={'satPolicy':'required-alternatives','note':L('Official international checklist requires ACT, SAT and/or CLT. An English test does not replace this academic requirement. Conditional English admission is not offered.','Официальный международный список требует ACT, SAT и/или CLT. Языковой тест не заменяет это академическое требование. Условный приём по английскому не предлагается.')},documents=[L('Certified international school evaluation within 90 days of application; limited school-category waivers, school records, national exams and Common App essay/short answers.','Заверенная международная оценка школы в течение 90 дней после заявки; ограниченные школьные освобождения, оценки, национальные экзамены и эссе/короткие ответы Common App.')],sources=[s('https://udallas.edu/admissions-aid/undergraduate/international-students/','University of Dallas international bachelor checklist','University of Dallas: международный бакалаврский список')])],'Kept required academic alternatives independent from English and distinguished University of Dallas from UT Dallas.', ['Page still names Fall 2026 rolling admission; Fall 2027 confirmation, IELTS variant/sections and exact CLT academic conditions remain unconfirmed.'])
